(async () => {
  const v = document.getElementById('v');
  const c = document.getElementById('c');
  const ctx = c.getContext('2d', { willReadFrequently: true });

  function waitFrame(video) {
    return new Promise((resolve) => {
      if (video.requestVideoFrameCallback) {
        video.requestVideoFrameCallback((now, meta) => resolve(meta));
      } else {
        requestAnimationFrame(() => requestAnimationFrame(resolve));
      }
    });
  }

  async function seekAndDraw(t) {
    v.currentTime = t;
    await new Promise((resolve) => {
      const onSeeked = () => { v.removeEventListener('seeked', onSeeked); resolve(); };
      v.addEventListener('seeked', onSeeked);
    });
    await waitFrame(v);
    ctx.clearRect(0, 0, 1920, 1080);
    ctx.drawImage(v, 0, 0);
    const d = ctx.getImageData(0, 0, 1920, 1080).data;
    function px(x, y) {
      const off = (y * 1920 + x) * 4;
      return [d[off], d[off+1], d[off+2], d[off+3]];
    }
    // also compute a checksum of alpha channel to see if ANY variation exists
